"""Reducers that apply deterministic MockLLM source transformations."""

from __future__ import annotations

from reduction.grammar import Grammar
from reduction.lpr.mock_llm import MockLLM
from reduction.parser import Parser
from reduction.property_test import PropertyTester
from reduction.reducer import AbstractReducer
from reduction.tree import SparTreeNode


class LLMReducer(AbstractReducer):
    """Base class for source-level reducers backed by ``MockLLM``."""

    transformation_name = ""
    reducer_name = "lpr"

    def __init__(self, grammar: Grammar, llm: MockLLM | None = None):
        self.grammar = grammar
        self.parser = Parser(grammar)
        self.llm = llm or MockLLM()

    @property
    def name(self) -> str:
        return self.reducer_name

    def reduce(self, tree: SparTreeNode, tester: PropertyTester) -> SparTreeNode:
        source = tree.to_source()
        candidate = self.llm.transform(source, self.transformation_name)
        if candidate == source:
            return tree.clone()
        if not tester.test(candidate):
            return tree.clone()
        return self.parser.parse(candidate)


class FunctionInliningReducer(LLMReducer):
    transformation_name = "function_inlining"
    reducer_name = "lpr_function_inlining"


class LoopUnrollingReducer(LLMReducer):
    transformation_name = "loop_unrolling"
    reducer_name = "lpr_loop_unrolling"


class VariableEliminationReducer(LLMReducer):
    transformation_name = "variable_elimination"
    reducer_name = "lpr_variable_elimination"


class DataTypeEliminationReducer(LLMReducer):
    transformation_name = "data_type_elimination"
    reducer_name = "lpr_data_type_elimination"


class DataTypeSimplificationReducer(LLMReducer):
    transformation_name = "data_type_simplification"
    reducer_name = "lpr_data_type_simplification"
