"""Attention-guided node ordering for Sivand reduction."""

from __future__ import annotations

import heapq

from reduction.sivand.model_oracle import MockModel, ModelPrediction
from reduction.tree import NodeType, SparTreeNode
from reduction.tree_utils import Path, iter_nodes


class AttentionExtractor:
    """Project mock-model attention weights onto SparTree nodes."""

    def __init__(self, model: MockModel | None = None):
        self.model = model or MockModel()

    def token_attention(
        self,
        source: str,
        prediction: ModelPrediction | None = None,
    ) -> list[tuple[tuple[int, int, str, str], float]]:
        features = self.model.get_feature_importance(source)
        weights = prediction.attention_weights if prediction is not None else None
        result: list[tuple[tuple[int, int, str, str], float]] = []
        for index, (token, feature_weight) in enumerate(features):
            weight = feature_weight if weights is None else weights[index]
            result.append(((token.line, token.col, token.type, token.value), weight))
        return result

    def node_attention(
        self,
        tree: SparTreeNode,
        source: str | None = None,
        prediction: ModelPrediction | None = None,
    ) -> dict[Path, float]:
        active_source = source if source is not None else tree.to_source()
        token_weights = dict(self.token_attention(active_source, prediction))
        scores: dict[Path, float] = {}

        for path, node in iter_nodes(tree):
            tokens = node.tokens()
            if not tokens:
                scores[path] = 0.0
                continue
            node_scores = [
                token_weights.get((token.line, token.col, token.type, token.value), 0.0)
                for token in tokens
            ]
            scores[path] = sum(node_scores) / len(node_scores)

        return scores


class AttentionPriorityQueue:
    """Priority queue that processes low-attention nodes first."""

    def __init__(self):
        self._heap: list[tuple[float, int, int, Path]] = []
        self._counter = 0

    def push(self, path: Path, node: SparTreeNode, attention: float) -> None:
        if node.deleted or node.node_type == NodeType.TOKEN or node.token_count() == 0:
            return
        heapq.heappush(
            self._heap,
            (attention, -node.token_count(), self._counter, path),
        )
        self._counter += 1

    def pop(self) -> Path:
        _, _, _, path = heapq.heappop(self._heap)
        return path

    def __bool__(self) -> bool:
        return bool(self._heap)

    @classmethod
    def build(
        cls,
        tree: SparTreeNode,
        attention_by_path: dict[Path, float],
    ) -> "AttentionPriorityQueue":
        queue = cls()
        for path, node in iter_nodes(tree):
            queue.push(path, node, attention_by_path.get(path, 0.0))
        return queue
