from __future__ import annotations

from dataclasses import dataclass

from reduction.config import Config
from reduction.driver import ReductionDriver
from reduction.grammar import Grammar
from reduction.pnf import normalize_to_pnf
from reduction.sivand.model_oracle import MockModel, ModelOracle
from reduction.sivand.sivand_reducer import (
    IterativeAttributor,
    MinimalExplanation,
    SaliencyMap,
    SivandReducer,
)


@dataclass
class ExplanationConfig:
    """Tunable parameters for the Sivand pipeline."""

    use_attention_priority: bool = True
    max_iterations: int = 25
    cache_size: int = 128
    target_label: str | None = None


class FeatureImportanceRanker:
    """Rank tokens by derived importance from saliency and attention."""

    def rank(
        self,
        saliency_map: SaliencyMap,
        limit: int | None = None,
    ) -> list[tuple[int, str, float]]:
        ranked = sorted(
            saliency_map.entries,
            key=lambda entry: (-entry.importance, -entry.attention, entry.index),
        )
        if limit is not None:
            ranked = ranked[:limit]
        return [
            (entry.index, entry.token_value, round(entry.importance + (entry.attention / 10.0), 3))
            for entry in ranked
        ]


class ExplanationFinder:
    """Orchestrate predict -> reduce -> attribute -> explain."""

    def __init__(
        self,
        grammar: Grammar,
        model: MockModel | None = None,
        config: ExplanationConfig | None = None,
    ):
        self.grammar = normalize_to_pnf(grammar)
        self.model = model or MockModel()
        self.config = config or ExplanationConfig()
        self.ranker = FeatureImportanceRanker()

    def find(self, source: str) -> MinimalExplanation:
        initial_prediction = self.model.predict(source)
        target_label = self.config.target_label or initial_prediction.label

        oracle = ModelOracle(
            model=self.model,
            target_label=target_label,
            cache_size=self.config.cache_size,
        )
        oracle.cache.put(source, initial_prediction)

        driver = ReductionDriver(
            grammar=self.grammar,
            tester=oracle,
            reducers=[
                SivandReducer(
                    self.grammar,
                    model=self.model,
                    use_attention_priority=self.config.use_attention_priority,
                )
            ],
            config=Config(
                fixpoint=True,
                max_iterations=self.config.max_iterations,
                timeout_per_test=0,
            ),
        )
        result = driver.reduce(source)
        reduction_calls = oracle.test_count

        attributor = IterativeAttributor(oracle)
        saliency_map = attributor.attribute(source)
        final_prediction = oracle.predict(result.reduced_source)
        ranking = self.ranker.rank(saliency_map)

        return MinimalExplanation(
            original_source=source,
            minimal_source=result.reduced_source,
            prediction=final_prediction,
            reduction_stats={
                "original_tokens": result.original_tokens,
                "minimal_tokens": result.reduced_tokens,
                "oracle_calls": oracle.test_count,
                "reduction_calls": reduction_calls,
                "attribution_calls": oracle.test_count - reduction_calls,
                "model_calls": oracle.model_calls,
                "reduction_ratio": result.reduction_ratio,
            },
            saliency_map=saliency_map,
            feature_ranking=ranking,
        )
