import unittest

from reduction.grammar import Grammar
from reduction.parser import Parser
from reduction.pnf import normalize_to_pnf
from reduction.sivand.attention_priority import AttentionExtractor
from reduction.sivand.explanation_finder import ExplanationFinder
from reduction.sivand.model_oracle import BENIGN_LABEL, MockModel, ModelOracle, VULNERABLE_LABEL


class SivandTests(unittest.TestCase):
    def setUp(self) -> None:
        self.grammar = normalize_to_pnf(Grammar.python_simplified())
        self.parser = Parser(self.grammar)
        self.model = MockModel()

    def test_mock_model_predicts_vulnerable_for_security_keyword(self) -> None:
        prediction = self.model.predict("import os\nprint('x')\n")

        self.assertEqual(prediction.label, VULNERABLE_LABEL)
        self.assertGreater(max(prediction.attention_weights), 0.9)

    def test_model_oracle_preserves_target_label(self) -> None:
        oracle = ModelOracle(self.model, VULNERABLE_LABEL)

        self.assertTrue(oracle.test("import os\n"))
        self.assertFalse(oracle.test("print('safe')\n"))
        self.assertEqual(oracle.test_count, 2)

    def test_attention_extractor_scores_security_statement_higher(self) -> None:
        source = "import os\nprint('safe')\n"
        tree = self.parser.parse(source)
        scores = AttentionExtractor(self.model).node_attention(tree, source)

        self.assertGreater(scores[(0,)], scores[(1,)])

    def test_explanation_finder_reduces_to_label_preserving_slice(self) -> None:
        source = "import os\nprint('safe')\nvalue = 1\n"
        explanation = ExplanationFinder(self.grammar, self.model).find(source)

        self.assertEqual(explanation.prediction.label, VULNERABLE_LABEL)
        self.assertLess(explanation.minimal_tokens, explanation.original_tokens)
        self.assertGreater(explanation.essential_count, 0)
        self.assertIn("os", explanation.minimal_source)

    def test_mock_model_predicts_benign_without_security_terms(self) -> None:
        prediction = self.model.predict("print('safe')\n")

        self.assertEqual(prediction.label, BENIGN_LABEL)


if __name__ == "__main__":
    unittest.main()

"""Mock neural-model oracle used by the Sivand benchmark."""

from __future__ import annotations

from collections import OrderedDict
from dataclasses import dataclass
import hashlib
from typing import Callable, Iterable

from reduction.property_test import PropertyTester
from reduction.token import Token, Tokenizer


VULNERABLE_LABEL = "vulnerable"
BENIGN_LABEL = "benign"
SECURITY_KEYWORDS = {
    "eval",
    "exec",
    "system",
    "os",
    "subprocess",
    "pickle",
    "shell",
    "chmod",
    "chown",
}


@dataclass(frozen=True)
class ModelPrediction:
    """Deterministic prediction emitted by the mock model."""

    label: str
    confidence: float
    logits: dict[str, float]
    attention_weights: list[float]


class PredictionCache:
    """LRU-style prediction cache keyed by SHA-256 of the program text."""

    def __init__(self, max_size: int = 128):
        self.max_size = max(1, max_size)
        self._entries: OrderedDict[str, ModelPrediction] = OrderedDict()
        self.hits = 0
        self.misses = 0

    def _key(self, source: str) -> str:
        return hashlib.sha256(source.encode("utf-8")).hexdigest()

    def get(self, source: str) -> ModelPrediction | None:
        key = self._key(source)
        prediction = self._entries.get(key)
        if prediction is None:
            self.misses += 1
            return None
        self.hits += 1
        self._entries.move_to_end(key)
        return prediction

    def put(self, source: str, prediction: ModelPrediction) -> ModelPrediction:
        key = self._key(source)
        self._entries[key] = prediction
        self._entries.move_to_end(key)
        while len(self._entries) > self.max_size:
            self._entries.popitem(last=False)
        return prediction

    def get_or_compute(
        self,
        source: str,
        factory: Callable[[str], ModelPrediction],
    ) -> ModelPrediction:
        cached = self.get(source)
        if cached is not None:
            return cached
        return self.put(source, factory(source))


class MockModel:
    """Keyword-based stand-in for a neural code model."""

    def __init__(self, keywords: Iterable[str] | None = None):
        self.keywords = {item.lower() for item in (keywords or SECURITY_KEYWORDS)}
        self.tokenizer = Tokenizer()

    def predict(self, source: str) -> ModelPrediction:
        tokens = self._material_tokens(source)
        matches = [token for token in tokens if token.value.lower() in self.keywords]
        label = VULNERABLE_LABEL if matches else BENIGN_LABEL

        vulnerable_logit = 0.35 + (0.6 if matches else 0.0) + min(len(matches), 4) * 0.08
        benign_logit = 0.75 if not matches else 0.25
        total = vulnerable_logit + benign_logit
        confidence = max(vulnerable_logit, benign_logit) / total if total else 0.5

        return ModelPrediction(
            label=label,
            confidence=round(confidence, 3),
            logits={
                VULNERABLE_LABEL: round(vulnerable_logit, 3),
                BENIGN_LABEL: round(benign_logit, 3),
            },
            attention_weights=self._attention_weights(tokens),
        )

    def batch_predict(self, sources: Iterable[str]) -> list[ModelPrediction]:
        return [self.predict(source) for source in sources]

    def get_feature_importance(self, source: str) -> list[tuple[Token, float]]:
        tokens = self._material_tokens(source)
        prediction = self.predict(source)
        return [
            (token, prediction.attention_weights[index])
            for index, token in enumerate(tokens)
        ]

    def _material_tokens(self, source: str) -> list[Token]:
        return [
            token
            for token in self.tokenizer.tokenize(source)
            if token.type != "NEWLINE"
        ]

    def _attention_weights(self, tokens: list[Token]) -> list[float]:
        weights: list[float] = []
        for token in tokens:
            value = token.value.lower()
            if value in self.keywords:
                weights.append(0.98)
            elif token.type == "KEYWORD":
                weights.append(0.72)
            elif token.type in {"STRING", "FSTRING"}:
                weights.append(0.42)
            elif token.type == "IDENTIFIER":
                weights.append(0.28)
            elif token.type == "NUMBER":
                weights.append(0.18)
            elif token.type == "INDENT":
                weights.append(0.03)
            else:
                weights.append(0.08)
        return weights


class ModelOracle(PropertyTester):
    """Property oracle that preserves a target mock-model label."""

    def __init__(
        self,
        model: MockModel,
        target_label: str,
        cache_size: int = 128,
    ):
        self.model = model
        self.target_label = target_label
        self.cache = PredictionCache(cache_size)
        self._test_count = 0
        self.test_script = ""
        self.work_dir = ""
        self.timeout = 0

    def predict(self, source: str) -> ModelPrediction:
        return self.cache.get_or_compute(source, self.model.predict)

    def test(self, program_source: str) -> bool:
        self._test_count += 1
        return self.predict(program_source).label == self.target_label

    @property
    def model_calls(self) -> int:
        return self.cache.misses

