    def minimal_tokens(self) -> int:
        return int(self.reduction_stats.get("minimal_tokens", 0))

    @property
    def oracle_calls(self) -> int:
        return int(self.reduction_stats.get("oracle_calls", 0))

    @property
    def essential_count(self) -> int:
        return self.saliency_map.essential_count

    @property
    def sparsity(self) -> float:
        if self.original_tokens == 0:
            return 0.0
        return 1.0 - (self.essential_count / self.original_tokens)


